mapper.select:
SELECT c.chunk_id AS chunkId, c.doc_id AS docId, c.content, c.title, c.indicator_code AS indicatorCode, c.specialty, c.url, d.kb_version AS kbVersion, d.authority_level AS authorityLevel FROM report_kb_chunk c INNER JOIN report_kb_document d ON d.doc_id = c.doc_id WHERE d.status = 'PUBLISHED' AND d.effective_from <= #{now} AND (d.effective_to IS NULL OR d.effective_to > #{now})
AND c.indicator_code = #{indicatorCode}
AND c.specialty = #{specialty}
ORDER BY c.chunk_id
